mapper.select:
select s.sku_id, s.style_id, s.style_no, s.sku_code, s.color_code, s.color_name, s.size_code, s.size_name, s.barcode, s.retail_price, s.status, s.del_flag, s.create_by, s.create_time, s.update_by, s.update_time, s.remark, st.style_name from erp_style_sku s left join erp_style st on st.style_id = s.style_id
s.del_flag = '0' and s.style_no like concat('%', #{styleNo}, '%') and s.sku_code like concat('%', #{skuCode}, '%') and s.color_name like concat('%', #{colorName}, '%') and s.size_name like concat('%', #{sizeName}, '%') and s.status = #{status}
order by s.style_no asc, s.sku_id asc
